'One static road-machine display yard, one scene and zero new independent models. Three complete qualified machines retain unit scale and every original local position/normal/index buffer, material dictionary and internal hierarchy: the whole grader spans a genuine shallow long floor recess with all six whole tyre soles supported on the two side decks; the whole tracked paver is quarter-turned in the rear left bay and the whole single-drum roller stays separately in the forward left bay. A broad open middle strip and front apron separate the intact machines. One closed scene-only slab has a real lowered recess bottom and four inner walls, not a dark decal or a cap at deck level. This is not the old excavator behind entrance barriers, nor the flat aviation ground-service holding corner. The initial plain three-machine parking idea was rejected before any source because its spatial relation was too similar. No old model is extracted, resized, recoloured or counted anew. The recess is a shallow static display feature, not a human inspection pit or access route. No grading, paving, compaction, maintenance procedure, moving wheels or articulation, machine coupling, traffic flow, structural support capacity, human clearance, accessibility, operation, installation or safety certification. Rigging, animation and interaction are not made and outside this static scope.'

import base64,copy,hashlib,json,math,struct,zlib

from pathlib import Path

ASSET='spacebase-whole-crew-on-open-airlock-threshold-scene-01'

TITLE='Whole Space Crew on the Open Airlock Threshold'

TOL=2e-7

INPUTS={'hatch': {'bytes': 19272, 'sha256': '34896befc5b2caba859bbfb599ca1acb813b900dff40419850a5a9fb606e0e43', 'compressed': ''}, 'crew': {'bytes': 131684, 'sha256': 'c6bd747882ad56559b6f2e617ec6272cb3ca3c3448968b11e390268c090ef96a', 'compressed': ''}}

SOURCE_INPUTS={'hatch': {'bytes': 28249, 'sha256': '5bb11307c86c6c8971e6089dda7d986b3b5d340c2c78bd21c67b0fd6b1bed7d3', 'compressed': ''}, 'crew': {'bytes': 27681, 'sha256': '637687a1cc63289b94db5d4b5ea254b7c93dae62d987933958dab6a4c607f409', 'compressed': ''}}

PALETTE=[('SceneOnlyThresholdSlab', (0.29, 0.32, 0.34, 1), 0.9)]

G={}

def record(name,v,fs,m):
 ts=[];mats=[]
 for i,f in enumerate(fs):
  for k in range(1,len(f)-1):ts.append((f[0],f[k],f[k+1]));mats.append(m[i] if isinstance(m,list)else m)
 vol=sum(sum(v[a][i]*([v[b][1]*v[c][2]-v[b][2]*v[c][1],v[b][2]*v[c][0]-v[b][0]*v[c][2],v[b][0]*v[c][1]-v[b][1]*v[c][0]][i])for i in range(3))for a,b,c in ts)/6
 if vol<0:ts=[(a,c,b)for a,b,c in ts]
 assert abs(vol)>1e-12;G[name]=(v,ts,mats)

def prism(name,p,z0,z1,m,transform=None):
 v=[(x,y,z)for z in[z0,z1]for x,y in p];n=len(p);f=[tuple(reversed(range(n))),tuple(range(n,2*n))]+[(i,(i+1)%n,(i+1)%n+n,i+n)for i in range(n)]
 if transform:v=[transform(q)for q in v]
 record(name,v,f,m)

def box(name,lo,hi,m,transform=None):prism(name,[(lo[0],lo[1]),(hi[0],lo[1]),(hi[0],hi[1]),(lo[0],hi[1])],lo[2],hi[2],m,transform)

def make_geometry():
 G.clear()
 box('SceneOnlyThresholdSlab',(-1.8,-1.8,0),(1.8,1.8,.12),0)
 return G

def pack_glb(doc,blob):
 j=json.dumps(doc,separators=(',',':'),allow_nan=False).encode();j+=b' '*((-len(j))%4)
 b=bytes(blob)+b'\0'*((-len(blob))%4)
 return struct.pack('<4sII',b'glTF',2,12+8+len(j)+8+len(b))+struct.pack('<II',len(j),0x4e4f534a)+j+struct.pack('<II',len(b),0x004e4942)+b

def compose_floor(inputs):
 make_geometry();d=dict(asset={'version':'2.0','generator':'Original static mesh construction'},scene=0,scenes=[{'name':TITLE,'nodes':[0]}],nodes=[{'name':'AssetRoot__'+ASSET,'children':[]}],meshes=[],materials=[{'name':n,'doubleSided':True,'pbrMetallicRoughness':{'baseColorFactor':c,'metallicFactor':0.,'roughnessFactor':r}}for n,c,r in PALETTE],accessors=[],bufferViews=[],buffers=[]);blob=bytearray()
 def array(values,component,kind):
  flat=[v for row in values for v in row]if kind=='VEC3'else values;fmt='f'if component==5126 else'I';raw=struct.pack('<'+fmt*len(flat),*flat);offset=len(blob);blob.extend(raw);blob.extend(b'\0'*((-len(blob))%4));view=len(d['bufferViews']);d['bufferViews'].append({'buffer':0,'byteOffset':offset,'byteLength':len(raw)});a={'bufferView':view,'componentType':component,'count':len(values),'type':kind}
  if kind=='VEC3':a.update(min=[min(p[k]for p in values)for k in range(3)],max=[max(p[k]for p in values)for k in range(3)])
  index=len(d['accessors']);d['accessors'].append(a);return index
 for name,(v,fs,mats)in G.items():
  prim=[]
  for mat in sorted(set(mats)):
   positions=[];normals=[]
   for ids,mi in zip(fs,mats):
    if mi!=mat:continue
    a,b,c=[v[i]for i in ids];u=[b[k]-a[k]for k in range(3)];w=[c[k]-a[k]for k in range(3)];n=(u[1]*w[2]-u[2]*w[1],u[2]*w[0]-u[0]*w[2],u[0]*w[1]-u[1]*w[0]);le=math.sqrt(sum(x*x for x in n));assert le>1e-12;n=[x/le for x in n];positions.extend((x,z,-y)for x,y,z in[a,b,c]);normals.extend([(n[0],n[2],-n[1])]*3)
   prim.append({'attributes':{'POSITION':array(positions,5126,'VEC3'),'NORMAL':array(normals,5126,'VEC3')},'indices':array(list(range(len(positions))),5125,'SCALAR'),'material':mat,'mode':4})
  mesh=len(d['meshes']);d['meshes'].append({'name':name,'primitives':prim});node=len(d['nodes']);d['nodes'].append({'name':name,'mesh':mesh});d['nodes'][0]['children'].append(node)
 d['buffers']=[{'byteLength':len(blob)}];return d,bytes(blob),{'new_original_geometry':True,'triangles':sum(len(f)for v,f,m in G.values()),'mesh_count':len(G),'whole_original_model_count':0,'static_pose_only':True}

PLACEMENTS=[('hatch', (0.0, 0.7, 0.12)), ('crew', (0.0, 0.81, 0.34))]

def decode_document(raw):
 assert raw[:4]==b'glTF';p=12;d=None;b=None
 while p<len(raw):
  n,k=struct.unpack_from('<II',raw,p);chunk=raw[p+8:p+8+n];p+=8+n
  if k==0x4e4f534a:d=json.loads(chunk)
  elif k==0x004e4942:b=chunk
 assert d is not None and b is not None;return d,b

def compose(inputs):
    d = dict(asset={'version': '2.0', 'generator': 'Complete original GLB payloads with rigid whole-instance parent wrappers'}, scene=0, scenes=[{'name': TITLE, 'nodes': [0]}], nodes=[{'name': 'WholeCrewAirlockThreshold', 'children': []}], materials=[], meshes=[], accessors=[], bufferViews=[], buffers=[])
    blob = bytearray()

    def append(doc, data, label, t):
        assert len(doc['buffers']) == 1 and (not any((doc.get(x) for x in ['skins', 'animations', 'textures', 'images'])))
        assert len(data) >= doc['buffers'][0]['byteLength']
        no, mo, ma, ac, bv = (len(d['nodes']), len(d['meshes']), len(d['materials']), len(d['accessors']), len(d['bufferViews']))
        offset = len(blob)
        blob.extend(data[:doc['buffers'][0]['byteLength']])
        blob.extend(b'\x00' * (-len(blob) % 4))
        d['materials'].extend(copy.deepcopy(doc['materials']))
        for v in doc['bufferViews']:
            v = copy.deepcopy(v)
            assert v.get('buffer', 0) == 0
            v['buffer'] = 0
            v['byteOffset'] = v.get('byteOffset', 0) + offset
            d['bufferViews'].append(v)
        for v in doc['accessors']:
            v = copy.deepcopy(v)
            assert 'sparse' not in v
            v['bufferView'] += bv
            d['accessors'].append(v)
        for m in doc['meshes']:
            m = copy.deepcopy(m)
            for p in m['primitives']:
                assert not p.get('targets')
                p['attributes'] = {k: v + ac for k, v in p['attributes'].items()}
                p['indices'] += ac
                p['material'] += ma
            d['meshes'].append(m)
        for n in doc['nodes']:
            n = copy.deepcopy(n)
            if label != 'SceneOnlyThresholdGeometry':
                n.setdefault('extras', {})['whole_original_node_name'] = n.get('name', '')
                n['name'] = label + '__' + n.get('name', '')
            if 'mesh' in n:
                n['mesh'] += mo
            if 'children' in n:
                n['children'] = [i + no for i in n['children']]
            d['nodes'].append(n)
        root = len(d['nodes'])
        d['nodes'].append(dict(name='WholeInstance_' + label, translation=[t[0], t[2], -t[1]], children=[no + i for i in doc['scenes'][doc.get('scene', 0)]['nodes']], extras={'unit_scale': True, 'whole_original_payload': True, 'translation_only_wrapper': True}))
        d['nodes'][0]['children'].append(root)
    for label, t in PLACEMENTS:
        v = INPUTS[label]
        raw = zlib.decompress(base64.b64decode(v['compressed']))
        assert len(raw) == v['bytes'] and hashlib.sha256(raw).hexdigest() == v['sha256']
        doc, data = decode_document(raw)
        append(doc, data, label, t)
    floor, data, proof = compose_floor({})
    append(floor, data, 'SceneOnlyThresholdGeometry', (0, 0, 0))
    d['buffers'] = [{'byteLength': len(blob)}]
    return (d, bytes(blob), dict(new_original_geometry=False, triangles=2204, mesh_count=20, whole_original_model_count=0, scene_count=1, complete_existing_instances=2, static_pose_only=True, original_payloads={k: {a: v[a] for a in ['bytes', 'sha256']} for k, v in INPUTS.items()}, rigid_placements=PLACEMENTS, quarterturn_z_labels=[]))

def main():
    import bpy, sys, time
    from mathutils import Vector
    OUT = Path(__file__).resolve().parent
    inputs = {k: zlib.decompress(base64.b64decode(v['compressed'])) for k, v in INPUTS.items()}
    for k, raw in inputs.items():
        assert hashlib.sha256(raw).hexdigest() == INPUTS[k]['sha256']
    for v in SOURCE_INPUTS.values():
        assert hashlib.sha256(zlib.decompress(base64.b64decode(v['compressed']))).hexdigest() == v['sha256']
    document, blob, proof = compose(inputs)
    model = pack_glb(document, blob)
    (OUT / 'model.glb').write_bytes(model)
    bpy.ops.object.select_all(action='SELECT')
    bpy.ops.object.delete(use_global=False)
    bpy.ops.import_scene.gltf(filepath=str(OUT / 'model.glb'))
    parts = [o for o in bpy.context.scene.objects if o.type == 'MESH']
    assert len(parts) == 20
    triangle_count = sum((len(p.vertices) - 2 for o in parts for p in o.data.polygons))
    assert triangle_count == proof['triangles']
    points = [o.matrix_world @ v.co for o in parts for v in o.data.vertices]
    lo = [min((v[k] for v in points)) for k in range(3)]
    hi = [max((v[k] for v in points)) for k in range(3)]
    assert abs(lo[2]) <= TOL and abs(lo[0] + hi[0]) <= TOL and (abs(lo[1] + hi[1]) <= TOL)
    assert len({m for o in parts for m in o.data.materials}) == 9
    scene = bpy.context.scene
    scene.render.engine = 'CYCLES'
    scene.cycles.samples = 128
    scene.cycles.use_adaptive_sampling = False
    scene.cycles.use_denoising = False
    for layer in scene.view_layers:
        layer.cycles.use_denoising = False
    scene.use_nodes = False
    scene.render.use_compositing = False
    scene.render.threads_mode = 'FIXED'
    scene.render.threads = 4
    scene.render.resolution_x = scene.render.resolution_y = 640
    scene.render.resolution_percentage = 100
    scene.world = scene.world or bpy.data.worlds.new('Neutral instrument preview')
    scene.world.use_nodes = True
    scene.world.node_tree.nodes['Background'].inputs['Color'].default_value = (0.3, 0.3, 0.3, 1)
    scene.world.node_tree.nodes['Background'].inputs['Strength'].default_value = 0.8
    scene.view_settings.view_transform = 'AgX'
    focus = Vector((0.0, 0.0, 1.2))

    def aim(o, pos):
        o.location = pos
        o.rotation_euler = (focus - o.location).to_track_quat('-Z', 'Y').to_euler()
    for name, pos, power, size in [('Key', (-4, -5, 7), 850, 5), ('Fill', (5, -2, 5), 500, 4), ('Rim', (2, 5, 6), 650, 4)]:
        bpy.ops.object.light_add(type='AREA', location=pos)
        o = bpy.context.object
        o.name = 'Preview_' + name
        o.data.energy = power
        o.data.shape = 'DISK'
        o.data.size = size
        aim(o, pos)
    bpy.ops.object.camera_add()
    cam = bpy.context.object
    cam.name = 'Preview_Camera'
    cam.data.type = 'ORTHO'
    scene.camera = cam
    aim(cam, (-5, -8, 4.5))
    bpy.context.view_layer.update()
    rot = cam.rotation_euler.to_quaternion()
    right = rot @ Vector((1, 0, 0))
    up = rot @ Vector((0, 1, 0))
    xx = [v.dot(right) for v in points]
    yy = [v.dot(up) for v in points]
    cam.location += right * ((min(xx) + max(xx)) / 2 - cam.location.dot(right)) + up * ((min(yy) + max(yy)) / 2 - cam.location.dot(up))
    cam.data.ortho_scale = max(max(xx) - min(xx), max(yy) - min(yy)) * 1.12
    bpy.ops.mesh.primitive_plane_add(size=200, location=(0, 0, -0.0003))
    ground = bpy.context.object
    ground.name = 'Preview_ground_not_asset'
    mat = bpy.data.materials.new('Preview_slate')
    mat.diffuse_color = (0.2, 0.24, 0.25, 1)
    ground.data.materials.append(mat)
    bpy.ops.wm.save_as_mainfile(filepath=str(OUT / 'source.blend'), compress=False)

    def config():
        return dict(engine=scene.render.engine, samples=scene.cycles.samples, adaptive=scene.cycles.use_adaptive_sampling, cycles_denoise=scene.cycles.use_denoising, view_layer_denoise=[x.cycles.use_denoising for x in scene.view_layers], compositor_nodes=scene.use_nodes, compositing=scene.render.use_compositing, threads_mode=scene.render.threads_mode, threads=scene.render.threads)
    qa = {'review_mode': 'SELF_REVIEW', 'status': 'GEOMETRY_CREATED_NEEDS_MAKER_REVIEW', 'asset_id': ASSET, 'asset': ASSET, 'source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(), 'glb_sha256': hashlib.sha256(model).hexdigest(), 'mesh_count': 20, 'mesh_objects': 20, 'triangles': triangle_count, 'materials': 9, 'bounds_min_m': lo, 'bounds_max_m': hi, 'composition': proof, 'native_readback_claim': False, 'normal_setter_or_vertex_bake_used': False, 'render_configuration': {'samples': 128, 'threads': 4, 'engine': 'CYCLES', 'denoising': False}}
    qa['native_saved_render_config'] = config()
    qa['render_configs'] = {}
    if '--geometry-only' not in sys.argv:
        view = sys.argv[sys.argv.index('--tier-single-view') + 1] if '--tier-single-view' in sys.argv else 'thumbnail'
        assert view in ['qa-front', 'thumbnail']
        scene.cycles.samples = 16 if view == 'qa-front' else 128
        qa['render_configs'][view] = config()
        scene.render.filepath = str(OUT / (view + '.png'))
        start = time.monotonic()
        bpy.ops.render.render(write_still=True)
        qa['render'] = {'view': view, 'samples': scene.cycles.samples, 'seconds': time.monotonic() - start, 'original_pixels_reviewed': False}
    (OUT / 'qa-report.json').write_text(json.dumps(qa, indent=2) + '\n')
    files = {}
    for role, name in [('glb', 'model.glb'), ('blend', 'source.blend'), ('generator', 'generate.py'), ('render', 'thumbnail.png')]:
        p = OUT / name
        if p.exists():
            files[role] = {'path': f'assets/spacebase/{ASSET}/v1.0.0/{name}', 'size': p.stat().st_size, 'sha256': hashlib.sha256(p.read_bytes()).hexdigest()}
    if len(files) == 4:
        meta = {'id': ASSET, 'version': '1.0.0', 'category': 'scenes', 'assetKind': 'scene', 'theme': 'spacebase', 'style': 'source-preserved-low-poly', 'title': TITLE, 'description': 'One static space-expedition threshold scene, zero new independent models. One entire qualified padded space-crew character stands on the actual raised lower throat of one entire original fixed-open airlock hatch, at original unit scale. Both complete boot sole patches contact the original narrow threshold surface; the complete crew stays inside the original convex octagonal opening in frontal projection, with clearance from the fixed side door and hinge blocks. One low closed scene-only slab supports the complete original hatch foot. All original local vertex/normal/index buffers, full material dictionaries and internal node hierarchies are preserved; only whole-instance parent translations are added. This is not the old three-equipment sampling apron or landing-pad/access-tower court, and no existing model is counted again. The hatch remains a free-standing static display, not a complete pressurized airlock room. No operation, pressure sealing, life support, wearable protection, human access or clearances, installation, load capacity, engineering or safety suitability is claimed. Rigging, animation and interaction are not made and outside scope.', 'bounds': dict(zip(['x', 'y', 'z'], [hi[k] - lo[k] for k in range(3)]), unit='m'), 'triangles': triangle_count, 'materials': 9, 'files': files, 'status': 'review', 'license': 'All rights reserved'}
        (OUT / 'metadata.json').write_text(json.dumps(meta, indent=2) + '\n')
    print('SCENE_STAGE_COMPLETE', ASSET, triangle_count)

if __name__=='__main__':main()
